@CrossOrigin
@RestController
@RequestMapping("/SupplierQuery")
public class SupplierQueryRestController extends BaseSpringRestController {
	
	public SupplierQueryRestController( SupplierService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Supplier using a UUID
     * @param		UUID supplierId
     * @return		Supplier
     */    
    @GetMapping("/load")
    public Supplier load( @RequestParam(required=true) UUID supplierId ) {
    	Supplier entity = null;

    	try {  
    		entity = service.getSupplier( new SupplierFetchOneSummary( supplierId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Supplier using Id " + supplierId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Supplier business objects
     * @return		Set<Supplier>
     */
    @GetMapping("/")
    public List<Supplier> loadAll() {                
    	List<Supplier> supplierList = null;
        
    	try {
            // load the Supplier
            supplierList = service.getAllSupplier();
            
            if ( supplierList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Suppliers" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Suppliers ", exc );
        	return null;
        }

        return supplierList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Supplier supplier = null;
    protected SupplierService service = null;
    private static final Logger LOGGER = Logger.getLogger(SupplierQueryRestController.class.getName());
    
}
